"""Source-bound latest completed full suites; drafts remain visually rejected."""
from pathlib import Path
import json,hashlib,html,os
from PIL import Image
r=Path(__file__).resolve().parents[3];b=r/'data/venue_refs/floor_plans_v3';out=b/'all_room_renders_latest';out.mkdir(exist_ok=True);sections=[];evidence=[]
for key,scene,suite,round_,receipt in [('office','commercial_office_floor_02','full_suite_r114_cpu',114,'candidate/render_receipt.json'),('residential','dual_unit_residential_floor_03','final_audit_r130_cpu',130,'candidate/render_receipt.json')]:
 d=b/scene/suite;a=json.loads((d/receipt).read_text());assert hashlib.sha256(Path(a['source']).read_bytes()).hexdigest()==a['source_sha256'];figs=[]
 expected=21 if key=='office' else 43;assert len(a['frames'])==expected
 for f in a['frames']:
  src=Path(f['path']);assert hashlib.sha256(src.read_bytes()).hexdigest()==f['sha256'];dst=out/(key+'_r'+str(round_)+'_'+f['name']+'.jpg');im=Image.open(src).convert('RGB');im.thumbnail((1100,1100));im.save(dst,quality=86)
  figs.append('<figure><figcaption>'+html.escape(f['name'])+'</figcaption><a href="'+html.escape(os.path.relpath(src,out))+'"><img loading="lazy" src="'+dst.name+'"></a></figure>')
 evidence.append(dict(scene=scene,round=round_,source=a['source'],source_sha256=a['source_sha256'],frame_count=expected,receipt=str(d/receipt),independent_review=str(d/'blind_visual_review.json') if key=='office' else str(b/scene/'full130_independent_review/review.json'),accepted=False))
 review_path=(d/'blind_visual_review.json') if key=='office' else b/scene/'full130_independent_review/review.json';detail_path=d/'report.html' if key=='office' else b/scene/'finalization/report.html';review_exists=review_path.exists();review_text='독립 검수 기록 있음 · 미승인' if review_exists else '독립 전체 검수 진행 · 미승인'
 sections.append('<section id="'+key+'"'+(' hidden' if key!='office' else '')+'><h2>'+html.escape(scene)+' · r'+str(round_)+'</h2><p>'+review_text+' · '+str(expected)+'개 뷰. '+('CPU21장.' if key=='office' else 'CPU43장.')+'</p><p><a href="'+html.escape(os.path.relpath(detail_path,out))+'">상세 검수 보고서</a>'+(' · <a href="'+html.escape(os.path.relpath(review_path,out))+'">독립 비평</a>' if review_exists else '')+'</p><div class="grid">'+''.join(figs)+'</div></section>')
(out/'evidence.json').write_text(json.dumps(evidence,indent=2))
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>전체 방 · 최신 완료 렌더</title><style>body{font:16px/1.6 system-ui;margin:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}figure{margin:8px}img{width:100%}button{padding:12px;margin:6px}section[hidden]{display:none}</style><h1>전체 방 · 최신 완료 렌더64장</h1><p>사무실 r114(21장)과 고정 주거 r130(43장)의 실제 완료 렌더64장입니다. 사무실114 전체 독립검수는 미달이고, 주거130은43장+참조5장 전체 독립검수 REF/REAL 미달입니다. 최신 저장 후보는 사무실115·주거133으로 이 전체 세트와 구분합니다. 주거132 욕실 문은 국소 A/B2쌍 직접·독립 검수 B선호,133 출입문2곳은 동일카메라 검수 대기입니다. 전체 실사성 승인·데이터셋 승격 없음. 작은 외부JPEG를 사용하며 클릭하면 원본PNG가 열립니다.</p><p><a href="../commercial_office_floor_02/full_suite_r114_cpu/report.html">사무실114 전체</a> · <a href="../dual_unit_residential_floor_03/finalization/report.html">주거130 전체43뷰</a> · <a href="../dual_unit_residential_floor_03/bathroom_door132_review/report.html">132 욕실문 검수</a> · <a href="../dual_unit_residential_floor_03/entry133_review/report.html">133 출입문 검수 대기</a> · <a href="evidence.json">소스·라운드 증거</a> · <a href="report_before_r130.html">이전116 전체 갤러리 보존본</a></p><nav><button data-tab="office">사무실21장</button><button data-tab="residential">주거43장</button></nav>'''+''.join(sections)+'''<script>for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const s of document.querySelectorAll('section'))s.hidden=s.id!==b.dataset.tab;};</script></html>'''
assert len(page.encode())<50000;(out/'report.html').write_text(page);print(out/'report.html',len(page.encode()))
